import Foundation
import XCTest
@testable import TravelRunner

final class RunnerEnvTests: XCTestCase {
    private let keys = LocalSupabaseKeys(
        anonKey: "local-anon", serviceRoleKey: "local-service", jwtSecret: "local-secret", publishableKey: "sb_publishable_local"
    )
    /// What `pnpm env:pull` writes for the booking portal (Doppler dev_booking).
    private let dopplerBooking = """
    # Generated by scripts/doppler-env.sh
    AMATEUR_SUPABASE_URL=https://hosted.supabase.co
    AMATEUR_SUPABASE_ANON_KEY=hosted-anon
    AMATEUR_SUPABASE_SIGNING_KEY=hosted-secret
    NEXT_PUBLIC_SUPABASE_URL=https://hosted.supabase.co
    NEXT_PUBLIC_WEBAPP_URL=https://travel.fastbreak-dev.ai
    ALGOLIA_APP_ID=shared
    """

    func testLocalModeOverridesEveryHostedSupabaseValue() {
        let local = render(.booking, .local, existing: "")
        let effective = layered(env: dopplerBooking, envLocal: local)

        XCTAssertEqual(effective["AMATEUR_SUPABASE_URL"], "http://localhost:54321")
        XCTAssertEqual(effective["AMATEUR_SUPABASE_ANON_KEY"], "local-anon")
        XCTAssertEqual(effective["AMATEUR_SUPABASE_SIGNING_KEY"], "local-secret")
        XCTAssertEqual(effective["NEXT_PUBLIC_SUPABASE_URL"], "http://localhost:54321")
        XCTAssertEqual(effective["LOCAL_SUPABASE_URL"], "http://localhost:54321")
        XCTAssertEqual(effective["SUPABASE_SERVICE_ROLE_KEY"], "local-service")
        XCTAssertEqual(effective["NEXT_PUBLIC_WEBAPP_URL"], "http://localhost:3002")
        XCTAssertEqual(effective["NEXT_PUBLIC_LOCAL_DEV"], "true")
        XCTAssertEqual(effective["ALGOLIA_APP_ID"], "shared")
    }

    func testRemoteModeHandsSupabaseBackToDoppler() {
        let local = render(.booking, .local, existing: "")
        let remote = render(.booking, .remote, existing: local)
        let effective = layered(env: dopplerBooking, envLocal: remote)

        XCTAssertEqual(effective["AMATEUR_SUPABASE_URL"], "https://hosted.supabase.co")
        XCTAssertEqual(effective["AMATEUR_SUPABASE_ANON_KEY"], "hosted-anon")
        XCTAssertNil(effective["LOCAL_SUPABASE_URL"])
        XCTAssertNil(effective["SUPABASE_SERVICE_ROLE_KEY"])
        XCTAssertNil(effective["NEXT_PUBLIC_LOCAL_DEV"])
        XCTAssertEqual(effective["NEXT_PUBLIC_WEBAPP_URL"], "http://localhost:3002")
        XCTAssertEqual(effective["LOGIN_URL"], RunnerEnv.remoteLoginURL)
    }

    func testOldRunnerLinesAreRemovedAndDeveloperLinesKept() {
        let oldStyle = """
        # my notes
        LOCAL_SUPABASE_URL=http://localhost:54321
        NEXT_PUBLIC_SUPABASE_URL=http://localhost:54321
        AMATEUR_SUPABASE_URL_DEV=http://localhost:54321
        export HOTELPLANNER_API_KEY=mine
        STRIPE_WEBHOOK_SECRET=whsec_old
        """
        let remote = render(.booking, .remote, existing: oldStyle)

        XCTAssertTrue(remote.contains("# my notes"))
        XCTAssertTrue(remote.contains("export HOTELPLANNER_API_KEY=mine"))
        XCTAssertFalse(remote.contains("LOCAL_SUPABASE_URL"))
        XCTAssertFalse(remote.contains("NEXT_PUBLIC_SUPABASE_URL"))
        XCTAssertFalse(remote.contains("AMATEUR_SUPABASE_URL_DEV"))
        XCTAssertFalse(remote.contains("whsec_old"))
        XCTAssertEqual(remote.components(separatedBy: RunnerEnv.beginMarker).count, 2)
    }

    func testRenderIsIdempotentAndKeepsOneBlock() {
        let once = render(.partner, .local, existing: "CUSTOM=1\n")
        let twice = render(.partner, .local, existing: once)
        XCTAssertEqual(once, twice)
        XCTAssertTrue(once.hasPrefix("CUSTOM=1\n\n\(RunnerEnv.beginMarker)\n"))
        XCTAssertTrue(once.hasSuffix("\(RunnerEnv.endMarker)\n"))
    }

    func testStripeSecretLivesInTheBookingBlock() {
        let values = Dictionary(uniqueKeysWithValues: RunnerEnv.values(
            for: .booking, mode: .remote, host: "localhost", keys: keys, stripeWebhookSecret: "whsec_new"
        ))
        XCTAssertEqual(values["STRIPE_WEBHOOK_SECRET"], "whsec_new")
    }

    func testPartnerLocalAndLanValues() {
        let lan = Dictionary(uniqueKeysWithValues: RunnerEnv.values(
            for: .partner, mode: .local, host: "10.0.0.5", keys: keys, stripeWebhookSecret: "whsec_x"
        ))
        XCTAssertEqual(lan["AMATEUR_SUPABASE_URL"], "http://10.0.0.5:54321")
        XCTAssertEqual(lan["NEXT_PUBLIC_WEBAPP_URL"], "http://10.0.0.5:3006")
        XCTAssertEqual(lan["UNIVERSAL_LOGIN_URL"], "http://10.0.0.5:3000/login/init")
        XCTAssertEqual(lan["NEXT_PUBLIC_TRAVEL_BOOKING_PORTAL_URL"], "http://10.0.0.5:3002")
        XCTAssertEqual(lan["NEXT_PUBLIC_SUPABASE_PUBLISHABLE_DEFAULT_KEY"], "sb_publishable_local")
        XCTAssertNil(lan["STRIPE_WEBHOOK_SECRET"])

        let remote = Dictionary(uniqueKeysWithValues: RunnerEnv.values(
            for: .partner, mode: .remote, host: "localhost", keys: keys, stripeWebhookSecret: nil
        ))
        XCTAssertNil(remote["UNIVERSAL_LOGIN_URL"], "remote keeps Doppler's hosted login")
        XCTAssertNil(remote["AMATEUR_SUPABASE_URL"])
    }

    func testLocalModeWithoutKeysWritesNoSupabaseValues() {
        let values = Dictionary(uniqueKeysWithValues: RunnerEnv.values(
            for: .booking, mode: .local, host: "localhost", keys: nil, stripeWebhookSecret: nil
        ))
        XCTAssertNil(values["AMATEUR_SUPABASE_URL"])
        XCTAssertEqual(values["NEXT_PUBLIC_WEBAPP_URL"], "http://localhost:3002")
    }

    func testParseStatusEnv() {
        let output = """
        ANON_KEY="eyJanon"
        API_URL="http://127.0.0.1:54321"
        JWT_SECRET="super-secret"
        PUBLISHABLE_KEY="sb_publishable_x"
        SERVICE_ROLE_KEY="eyJservice"
        """
        XCTAssertEqual(
            LocalSupabaseKeys.parse(statusEnv: output),
            LocalSupabaseKeys(anonKey: "eyJanon", serviceRoleKey: "eyJservice", jwtSecret: "super-secret", publishableKey: "sb_publishable_x")
        )
        XCTAssertNil(LocalSupabaseKeys.parse(statusEnv: "API_URL=x"))
    }

    // MARK: - Helpers

    private func render(_ app: RunnerEnv.App, _ mode: RunnerEnv.Mode, existing: String) -> String {
        RunnerEnv.render(
            existing: existing,
            values: RunnerEnv.values(for: app, mode: mode, host: "localhost", keys: keys, stripeWebhookSecret: nil),
            managedKeys: RunnerEnv.managedKeys(for: app)
        )
    }

    /// Next.js precedence: `.env.local` over `.env`.
    private func layered(env: String, envLocal: String) -> [String: String] {
        parse(env).merging(parse(envLocal)) { _, local in local }
    }

    private func parse(_ content: String) -> [String: String] {
        var values: [String: String] = [:]
        for line in content.components(separatedBy: "\n") {
            guard let key = RunnerEnv.assignedKey(line), let eq = line.firstIndex(of: "=") else { continue }
            values[key] = String(line[line.index(after: eq)...])
        }
        return values
    }
}
